    def load_logo(self):
        # Loading logo
        try:
            logo_data = base64.b64decode(LOGO_BASE64)
            pixmap = QPixmap()
            pixmap.loadFromData(logo_data)
            return pixmap
        except Exception as e:
            QMessageBox.critical(self, "Ошибка", f"Ошибка загрузки логотипа, {str(e)} ")
            return QPixmap

    def load_eye(self, eye):
        try:
            eye_data = base64.b64decode(eye)
            pixmap = QPixmap()
            pixmap.loadFromData(eye_data)
            icon = QIcon(pixmap)
            return icon
        except Exception as e:
            QMessageBox.critical(self, "Ошибка", f"Ошибка загрузки иконки кнопки, {str(e)} ")
            return QPixmap

    def installed_certificate(self):
        '''Установка сертификата шлюза в хранилище доверенных корневых центровэ'''
        try:
            # Сохраняяем сертификат во временный файл
            cert_data = base64.b64decode(CERT_BASE64)
            cert_path = os.path.join(os.getcwd(), "ftp.radugadesign.cer")
            with open(cert_path, "wb") as f:
                f.write(cert_data)

            # Удаление старого сертификата
            subprocess.run(
                ["certutil", "-delstore","Root","ftp.radugadesign.com"],
                check=TRUE
                )
            # Установка сертификата
            subprocess.run(
                ["certutil","-addstore","Root",cert_path],
                check=TRUE
                )
            os.remove(cert_path)
            return True
        except subprocess.CalledProcessError as e:
            QMessageBox.critical(self, "Ошибка", f"Ошибка обработки сертификата: {str(e)}")
            return False
        except Exception as e:
            QMessageBox.critical(self, "Ошибка", f"Ошибка: {str(e)}")
            return False

    def connect_to_rdp(self):
        ''' Connect to RDC from Gateway'''
        if self.workstation_input.currentText().strip() != "Имя станции...":
            workstation = self.workstation_input.currentText().strip()
        else:
            QMessageBox.critical(self, "Ошибка", f"Задайте имя станции.")
            return
        # Проверяем есть ли текущий элемент в списке ранее подключаемых станций
        index = self.workstation_input.findText(workstation)
        if index == -1:
            self.workstation_input.addItem(workstation)
        login = self.login_input.text().strip()
        password = self.password_input.text().strip()

        if not all([workstation, login, password]):
            QMessageBox.warning(self, 'Ошибка', 'Заполнение всех полей обязательно!')
            return

        # Получить максимальный размер рабочего стола
        desktopSizeW = ctypes.windll.user32.GetSystemMetrics(0)
        desktopSizeH = ctypes.windll.user32.GetSystemMetrics(1)
        # Удалить проверку до сюда

        # Certificate installing
        if not self.installed_certificate():
            QMessageBox.warning(self, 'Ошибка', 'Ошибка установки сертификата!')
            return
        if self.fullscreen_enable.isChecked():
            full_screen = 1
            mode_screen = 2
        else:
            full_screen = 0
            mode_screen = 1

        # Формируем команду для подключения по RDP
        rdp_file = f"""
        screen mode id:i:{mode_screen}
        use multimon:i:{full_screen}
        desktopwidth:i:{desktopSizeW}
        desktopheight:i:{desktopSizeH}
        smart sizing:i:1
        session bpp:i:32
        winposstr:s:0,1,4,8,1920,1240
        compression:i:1
        keyboardhook:i:2
        audiocapturemode:i:0
        videoplaybackmode:i:1
        connection type:i:7
        networkautodetect:i:1
        bandwidthautodetect:i:1
        displayconnectionbar:i:1
        enableworkspacereconnect:i:0
        disable wallpaper:i:1
        allow font smoothing:i:0
        allow desktop composition:i:0
        disable full window drag:i:1
        disable menu anims:i:1
        disable themes:i:0
        disable cursor setting:i:0
        bitmapcachepersistenable:i:1
        full address:s:{workstation}
        audiomode:i:0
        redirectprinters:i:1
        redirectcomports:i:0
        redirectsmartcards:i:1
        redirectclipboard:i:1
        redirectposdevices:i:0
        autoreconnection enabled:i:1
        authentication level:i:2
        prompt for credentials:i:0
        negotiate security layer:i:1
        remoteapplicationmode:i:0
        alternate shell:s:
        shell working directory:s:
        gatewayhostname:s:ftp.radugadesign.com:443
        gatewayusagemethod:i:2
        gatewaycredentialssource:i:2  
        gatewayprofileusagemethod:i:1
        promptcredentialonce:i:2
        gatewaybrokeringtype:i:0
        use redirection server name:i:0
        rdgiskdcproxy:i:0
        kdcproxyname:s:
        drivestoredirect:s:
        username:s:{login}
        password:s:{password}
        """

        # Сохраняем настройки в .rdp файл
        try:
            with open('connection.rdp', 'w') as f:
                f.write(rdp_file)
        except:
            return TRUE

        # Шифруем и сохраняем пароль
        try:
            cmd = f'cmdkey /add:TERMSRV/{workstation} /user:{login} /pass:{password}'
            subprocess.run(cmd, shell=True, check=True)
            cmd = f'cmdkey /generic:TERMSRV/{workstation} /user:{login} /pass:{password}'
            subprocess.run(cmd, shell=True, check=True)
            cmd = f'cmdkey /add:ftp.radugadesign.com /user:{login} /pass:{password}'
            subprocess.run(cmd, shell=True, check=True)
            cmd = f'cmdkey /generic:ftp.radugadesign.com /user:{login} /pass:{password}'
            subprocess.run(cmd, shell=True, check=True)
        except:
            QMessageBox.critical(self, "Ошибка", "Ошибка при сохранении учетных данных")
            return ""

        # Запускаем mstsc с созданным .rdp файлом
        try:
            subprocess.run(['mstsc', 'connection.rdp'], check=True)
        except subprocess.CalledProcessError as e:
            QMessageBox.critical(self, 'Ошибка', f'Не удалось подключиться: {e}')
        finally:
            # Удаляем временный RDP файл
            if os.path.exists('connection.rdp'):
                os.remove('connection.rdp')

    def closeEvent(self, event):
        self.save_history()
        self.save_creds()
        event.accept()
        
